// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EvaluationDatasetVersion) predicate.EvaluationDatasetVersion {
	return predicate.EvaluationDatasetVersion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EvaluationDatasetVersion) predicate.EvaluationDatasetVersion {
	return predicate.EvaluationDatasetVersion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EvaluationDatasetVersion) predicate.EvaluationDatasetVersion {
	return predicate.EvaluationDatasetVersion(sql.NotPredicates(p))
}
